const cfg = $item(0).$node['Config'].json || {};
const dryRun = !!cfg.defaultDryRun;
const locationId = String(cfg.locationId || '').trim();
const apiBaseUrl = String(cfg.apiBaseUrl || 'https://services.leadconnectorhq.com').replace(/\/$/, '');
const apiKey = String(cfg.apiKey || '').trim();
const queueTag = String(cfg.queueTag || 'Enrollment Queue - Emerald').trim();
const senderFieldName = String(cfg.senderFieldName || 'marketing_sender_email').trim();
const warmupWeek = Math.max(1, Math.trunc(Number(cfg.warmupWeekOverride || 1)));

if (!locationId) throw new Error('Missing locationId');
if (!dryRun && !apiKey) throw new Error('Missing apiKey in live mode');

const nowEt = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/New_York' }));
const nowPt = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Los_Angeles' }));
const etHour = nowEt.getHours();
const ptHour = nowPt.getHours();
const isSundayEt = nowEt.getDay() === 0;
const withinDispatchWindow = !isSundayEt && etHour >= 8 && ptHour < 17;

let senders = [];
try {
  senders = JSON.parse(String(cfg.sendersJson || '[]'));
} catch {
  throw new Error('Invalid sendersJson');
}

senders = senders.filter((s) => s && s.active !== false && s.email).map((s) => ({
  email: String(s.email).toLowerCase().trim(),
  weight: Math.max(1, Math.trunc(Number(s.weight || 1))),
  cap: warmupWeek <= 1 ? Number(s.capWeek1 || 50) : warmupWeek === 2 ? Number(s.capWeek2 || 75) : Number(s.capWeek3 || 100),
}));
if (!senders.length) throw new Error('No active senders');

const candidates = $items('Fetch Emerald Candidates').map((i) => i.json || {});
const inflight = $items('Estimate InFlight Due Today').map((i) => i.json || {});
const backlogTotal = Number($items('Count Unreleased Candidates')[0]?.json?.total_unreleased || 0);
const inflightMap = new Map(inflight.map((r) => [String(r.sender_email || '').toLowerCase(), Number(r.due_today || 0)]));

const minSafety = Math.max(1, Math.trunc(Number(cfg.minSafetyBuffer || 5)));
const pctSafety = Number(cfg.safetyBufferPct || 0.1);
for (const s of senders) {
  const safety = Math.max(minSafety, Math.round(s.cap * pctSafety));
  s.remaining = Math.max(0, s.cap - Number(inflightMap.get(s.email) || 0) - safety);
  s.safetyBuffer = safety;
  s.inFlightDueToday = Number(inflightMap.get(s.email) || 0);
}

const ring = [];
for (const s of senders) for (let i = 0; i < s.weight; i++) ring.push(s.email);
function hashString(str) { let h = 0; const s = String(str || ''); for (let i = 0; i < s.length; i++) h = ((h << 5) - h + s.charCodeAt(i)) | 0; return Math.abs(h); }
function pickSender(seedRaw) {
  if (!ring.length) return '';
  const seed = Math.abs(Number(seedRaw || 0)) || 0;
  const start = seed % ring.length;
  for (let i = 0; i < ring.length; i++) {
    const email = ring[(start + i) % ring.length];
    const sender = senders.find((x) => x.email === email);
    if (sender && sender.remaining > 0) { sender.remaining -= 1; return sender.email; }
  }
  return '';
}

async function doHttpRequest(options) {
  if (typeof $httpRequest === 'function') return await $httpRequest(options);
  if (this?.helpers?.httpRequest) return await this.helpers.httpRequest(options);
  throw new Error('HTTP helper not available');
}
async function apiRequest(method, path, body) {
  const options = { method, url: `${apiBaseUrl}${path}`, headers: { Authorization: `Bearer ${apiKey}`, Version: '2021-07-28', 'Content-Type': 'application/json', Accept: 'application/json' }, json: true };
  if (body !== undefined) options.body = body;
  try {
    const data = await doHttpRequest.call(this, options);
    return { ok: true, data };
  } catch (err) {
    return { ok: false, data: err?.response?.body || err?.message || err };
  }
}
function isValidTimeZone(tz) { try { new Intl.DateTimeFormat('en-US', { timeZone: tz }); return true; } catch { return false; } }
const usStateToTz = { AL:'America/Chicago', AK:'America/Anchorage', AZ:'America/Phoenix', AR:'America/Chicago', CA:'America/Los_Angeles', CO:'America/Denver', CT:'America/New_York', DE:'America/New_York', FL:'America/New_York', GA:'America/New_York', HI:'Pacific/Honolulu', ID:'America/Denver', IL:'America/Chicago', IN:'America/Indiana/Indianapolis', IA:'America/Chicago', KS:'America/Chicago', KY:'America/New_York', LA:'America/Chicago', ME:'America/New_York', MD:'America/New_York', MA:'America/New_York', MI:'America/New_York', MN:'America/Chicago', MS:'America/Chicago', MO:'America/Chicago', MT:'America/Denver', NE:'America/Chicago', NV:'America/Los_Angeles', NH:'America/New_York', NJ:'America/New_York', NM:'America/Denver', NY:'America/New_York', NC:'America/New_York', ND:'America/Chicago', OH:'America/New_York', OK:'America/Chicago', OR:'America/Los_Angeles', PA:'America/New_York', RI:'America/New_York', SC:'America/New_York', SD:'America/Chicago', TN:'America/Chicago', TX:'America/Chicago', UT:'America/Denver', VT:'America/New_York', VA:'America/New_York', WA:'America/Los_Angeles', WV:'America/New_York', WI:'America/Chicago', WY:'America/Denver', DC:'America/New_York' };
function norm(v) { return String(v || '').trim(); }
function resolveContactTimezone(c) {
  const explicit = norm(c.contact_timezone) || norm(c.timezone);
  if (explicit && isValidTimeZone(explicit)) return explicit;
  const state = norm(c.state).toUpperCase();
  return usStateToTz[state] || '';
}
let senderFieldId = '';
if (!dryRun) {
  const cf = await apiRequest('GET', `/locations/${locationId}/customFields?model=contact`);
  if (!cf.ok) throw new Error(`Failed custom fields lookup: ${JSON.stringify(cf.data)}`);
  const arr = Array.isArray(cf.data?.customFields) ? cf.data.customFields : Array.isArray(cf.data?.data?.customFields) ? cf.data.data.customFields : Array.isArray(cf.data?.data) ? cf.data.data : [];
  senderFieldId = arr.find((f) => String(f?.name || '').trim() === senderFieldName)?.id || '';
  if (!senderFieldId) throw new Error(`Missing GHL field: ${senderFieldName}`);
}

const runId = `${new Date().toISOString()}__emerald_sender_release`;
const out = [];
if (!withinDispatchWindow) {
  out.push({ json: { status: 'summary', summary: { ok: true, dryRun, runId, warmupWeek, windowOpen: false, windowLabel: 'Mon-Sat, 8:00 AM ET to 5:00 PM PT', sundayBlocked: isSundayEt, currentEtHour: etHour, currentPtHour: ptHour, candidates: 0, totalUnreleased: backlogTotal, backlogBeyondBatch: backlogTotal, planned: 0, queued: 0, deferred: 0, deferredOutsideBusinessHours: 0, deferredMissingTimezone: 0, errors: 0, warnings: [isSundayEt ? 'SUNDAY_BLOCKED: no dispatch on Sundays.' : 'DISPATCH_WINDOW_CLOSED: no contacts dispatched outside Mon-Sat 8:00 AM ET to 5:00 PM PT.'], senders: senders.map((s) => ({ email: s.email, cap: s.cap, inFlightDueToday: s.inFlightDueToday, safetyBuffer: s.safetyBuffer, remainingAfterPlan: s.remaining })) } } });
  return out;
}
for (const c of candidates) {
  const rowId = Number(c.emerald_row_id || 0);
  const email = String(c.email || '').trim();
  if (!email) { out.push({ json: { status: 'skipped_missing_email', emerald_row_id: c.emerald_row_id } }); continue; }
  const contactTz = resolveContactTimezone(c);
  if (!contactTz) { out.push({ json: { status: 'deferred_missing_timezone', emerald_row_id: rowId || null, email } }); continue; }
  const localNow = new Date(new Date().toLocaleString('en-US', { timeZone: contactTz }));
  const localHour = localNow.getHours();
  if (localHour < 8 || localHour >= 17) { out.push({ json: { status: 'deferred_outside_business_hours', emerald_row_id: rowId || null, email, timezone: contactTz, localHour } }); continue; }
  const sender = pickSender(rowId || hashString(email));
  if (!sender) { out.push({ json: { status: 'deferred_no_capacity', emerald_row_id: c.emerald_row_id, email } }); continue; }
  if (dryRun) { out.push({ json: { status: 'planned', emerald_row_id: c.emerald_row_id, email, sender_email: sender, timezone: contactTz, run_id: runId } }); continue; }
  let contactId = '';
  let contactSource = '';
  const dup = await apiRequest('GET', `/contacts/search/duplicate?locationId=${encodeURIComponent(locationId)}&email=${encodeURIComponent(email)}`);
  if (dup.ok && dup.data?.contact?.id) { contactId = String(dup.data.contact.id); contactSource = 'existing'; }
  if (!contactId) {
    const upsert = await apiRequest('POST', '/contacts/upsert', { locationId, email, firstName: c.first_name || undefined, lastName: c.last_name || undefined, phone: c.phone || undefined, companyName: c.company_name || undefined });
    if (!upsert.ok) { out.push({ json: { status: 'error_upsert', emerald_row_id: rowId || null, email, sender_email: sender, details: upsert.data } }); continue; }
    contactId = String(upsert.data?.contact?.id || upsert.data?.id || upsert.data?.contactId || '');
    contactSource = 'upsert';
  }
  if (!contactId) { out.push({ json: { status: 'error_contact_id', emerald_row_id: rowId || null, email, sender_email: sender, details: dup.data } }); continue; }
  const setField = await apiRequest('PUT', `/contacts/${contactId}`, { customFields: [{ id: senderFieldId, value: sender }] });
  if (!setField.ok) { out.push({ json: { status: 'error_set_sender', emerald_row_id: rowId || null, email, sender_email: sender, contact_id: contactId, details: setField.data } }); continue; }
  const tag = await apiRequest('POST', `/contacts/${contactId}/tags`, { tags: [queueTag] });
  if (!tag.ok) { out.push({ json: { status: 'error_add_queue_tag', emerald_row_id: rowId || null, email, sender_email: sender, contact_id: contactId, details: tag.data } }); continue; }
  out.push({ json: { status: 'queued', emerald_row_id: rowId || null, email, sender_email: sender, contact_id: contactId, contact_source: contactSource, timezone: contactTz, run_id: runId } });
}
const warnings = [];
if (dryRun) warnings.push('DRY_RUN_ACTIVE: no GHL writes or release log inserts are executed.');
warnings.push('QUEUE_TAG_PLACEHOLDER: confirm queueTag before activation.');
out.push({ json: { status: 'summary', summary: { ok: true, dryRun, runId, warmupWeek, windowOpen: true, windowLabel: 'Mon-Sat, 8:00 AM ET to 5:00 PM PT', sundayBlocked: isSundayEt, currentEtHour: etHour, currentPtHour: ptHour, candidates: candidates.length, totalUnreleased: backlogTotal, backlogBeyondBatch: Math.max(0, backlogTotal - candidates.length), planned: out.filter((x) => x.json.status === 'planned').length, queued: out.filter((x) => x.json.status === 'queued').length, deferred: out.filter((x) => String(x.json.status || '').startsWith('deferred_')).length, deferredOutsideBusinessHours: out.filter((x) => x.json.status === 'deferred_outside_business_hours').length, deferredMissingTimezone: out.filter((x) => x.json.status === 'deferred_missing_timezone').length, errors: out.filter((x) => String(x.json.status || '').startsWith('error_')).length, warnings, senders: senders.map((s) => ({ email: s.email, cap: s.cap, inFlightDueToday: s.inFlightDueToday, safetyBuffer: s.safetyBuffer, remainingAfterPlan: s.remaining })) } } });
return out;

const rows = $items('Dispatch + Queue (DryRun Safe)').map((i) => i.json || {});
const summary = rows.find((r) => r.status === 'summary') || null;
const sample = rows.filter((r) => r.status !== 'summary').slice(0, 20);
return [{ json: { ok: true, summary: summary?.summary || null, sample } }];
